class Solution {
public:
    vector<vector<string>> findMismatchedSegments(string s1, string s2) {
        int n = s1.size();
        vector<vector<string>> res;
        int i = 0;
        while (i < n) {
            if (s1[i] == s2[i]) {
                ++i;
            } else {
                int start = i;
                while (i < n && s1[i] != s2[i]) ++i;
                res.push_back({s1.substr(start, i - start), s2.substr(start, i - start)});
            }
        }
        return res;
    }
};
